"use client";

export {
  AomiBaseAccountProvider,
  type AomiBaseAccountProviderProps,
} from "./base-account";

"use client";

import { useEffect, useMemo, useState, type ReactNode } from "react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import type { Chain } from "viem";
import { http } from "viem";
import { WagmiProvider, createConfig, type Config } from "wagmi";
import { base, baseSepolia } from "wagmi/chains";
import { baseAccount } from "wagmi/connectors";
import type {
  SponsorshipPaymasterServiceContext,
  WalletEip712Payload,
  WalletTxPayload,
} from "@aomi-labs/react";
import {
  toViemSignMessageArgs,
  toViemSignTypedDataArgs,
} from "@aomi-labs/react";
import { AomiAuthAdapterProvider } from "../../context";
import { AOMI_AUTH_DISCONNECTED_IDENTITY } from "../../identity";
import { useFullTestnet } from "../../full-testnet-wallet-routing";
import {
  AomiWalletNetworkPreferencesProvider,
  useAomiWalletNetworkPreferences,
} from "../../network-preferences";
import {
  useSafeCapabilities,
  useSafeConnect,
  useSafeConnectors,
  useSafeDisconnect,
  useSafeSendCallsSync,
  useSafeSendTransaction,
  useSafeSignMessage,
  useSafeSignTypedData,
  useSafeSwitchChain,
  useSafeWagmiAccount,
  useSafeWagmiConfig,
} from "../../safe-wagmi-hooks";
import type { AomiAuthAdapter, AomiAuthIdentity } from "../../types";
import { ExtUserProvider, UserState, useUser } from "@aomi-labs/react";
import {
  executeAdapterTransaction,
  getPreferredRpcUrl,
} from "../../wallet-execution";

export type AomiBaseAccountProviderProps = {
  children: ReactNode;
  appName: string;
  appLogoUrl?: string | null;
  chains?: readonly [Chain, ...Chain[]];
  includeBaseSepolia?: boolean;
  sponsorship?: BaseAccountSponsorshipOptions;
};

export type BaseAccountSponsorshipOptions =
  | {
      mode?: "disabled";
    }
  | {
      mode: "optional";
      paymasterServiceContext?:
        | SponsorshipPaymasterServiceContext
        | ((chainId: number) => SponsorshipPaymasterServiceContext | undefined);
      paymasterServiceUrl?: string | ((chainId: number) => string | undefined);
      sendCallsTimeoutMs?: number;
    }
  | {
      // Temporary testing mode: fail closed instead of charging user ETH.
      mode: "required";
      paymasterServiceContext?:
        | SponsorshipPaymasterServiceContext
        | ((chainId: number) => SponsorshipPaymasterServiceContext | undefined);
      paymasterServiceUrl?: string | ((chainId: number) => string | undefined);
      sendCallsTimeoutMs?: number;
    };

const BASE_ACCOUNT_SDK_STORE_KEY = "base-acc-sdk.store";

function syncPersistedBaseAccountConfig({
  appName,
  appLogoUrl,
  chains,
}: {
  appName: string;
  appLogoUrl?: string | null;
  chains: readonly [Chain, ...Chain[]];
}) {
  const storage = globalThis.localStorage;
  if (!storage) return;

  try {
    const raw = storage.getItem(BASE_ACCOUNT_SDK_STORE_KEY);
    if (!raw) return;

    const parsed = JSON.parse(raw) as {
      state?: { config?: Record<string, unknown> };
    };
    if (!parsed.state?.config) {
      return;
    }

    parsed.state.config = {
      ...parsed.state.config,
      metadata: {
        appName,
        appLogoUrl: appLogoUrl ?? "",
        appChainIds: chains.map((chain) => chain.id),
      },
      paymasterUrls: {},
    };
    storage.setItem(BASE_ACCOUNT_SDK_STORE_KEY, JSON.stringify(parsed));
  } catch {
    // Ignore malformed persisted SDK state; connector initialization can recover.
  }
}

function createBaseAccountConfig({
  appName,
  appLogoUrl,
  chains,
}: {
  appName: string;
  appLogoUrl?: string | null;
  chains: readonly [Chain, ...Chain[]];
}): Config {
  syncPersistedBaseAccountConfig({ appName, appLogoUrl, chains });

  return createConfig({
    chains,
    connectors: [
      baseAccount({
        appName,
        appLogoUrl: appLogoUrl ?? null,
        paymasterUrls: {},
      }),
    ],
    transports: Object.fromEntries(
      chains.map((chain) => [chain.id, http(chain.rpcUrls.default.http[0])]),
    ),
    multiInjectedProviderDiscovery: false,
    ssr: true,
  });
}

function BaseAccountAdapterInner({
  children,
  sponsorship,
}: {
  children: ReactNode;
  sponsorship?: BaseAccountSponsorshipOptions;
}) {
  const { address, chainId, isConnected } = useSafeWagmiAccount();
  const connectors = useSafeConnectors();
  const { connectAsync, isPending: isConnecting } = useSafeConnect();
  const { disconnectAsync, isPending: isDisconnecting } = useSafeDisconnect();
  const { switchChainAsync, isPending: isSwitchingChain } =
    useSafeSwitchChain();
  const { sendTransactionAsync } = useSafeSendTransaction();
  const { sendCallsSyncAsync } = useSafeSendCallsSync();
  const { capabilities } = useSafeCapabilities();
  const { signTypedDataAsync } = useSafeSignTypedData();
  const { signMessageAsync } = useSafeSignMessage();
  const wagmiConfig = useSafeWagmiConfig();
  const {
    selectedEvmChainId,
    setSelectedEvmChainId,
    supportedSolanaNetworks,
  } = useAomiWalletNetworkPreferences();

  const chainsById = useMemo<Record<number, Chain>>(
    () =>
      Object.fromEntries(
        (wagmiConfig.chains ?? []).map((chain) => [chain.id, chain]),
      ),
    [wagmiConfig.chains],
  );

  useEffect(() => {
    if (
      !isConnected ||
      !selectedEvmChainId ||
      !switchChainAsync ||
      chainId === selectedEvmChainId
    ) {
      return;
    }
    void switchChainAsync({ chainId: selectedEvmChainId });
  }, [chainId, isConnected, selectedEvmChainId, switchChainAsync]);

  // Per-tx AA fields are session-owned: `session.ts` writes them to UserState
  // on tx-complete and we read them back via `useUser()`. This makes UserState
  // the single source of truth — identity rehydrates correctly after remount
  // (the previous local `useState<ResolvedAA>` was lost on unmount).
  const { user } = useUser();
  const userAAMode = UserState.aaMode(user);
  const userSmartAccount4337 = UserState.SmartAccount4337(user);
  const userDelegation7702 = UserState.Delegation7702(user);

  const adapter = useMemo<AomiAuthAdapter>(() => {
    const sponsorshipEnabled =
      sponsorship?.mode === "optional" || sponsorship?.mode === "required";
    const baseConnector =
      connectors.find((connector) => connector.id === "baseAccount") ??
      connectors.find((connector) => connector.type === "baseAccount") ??
      connectors[0];
    const identity: AomiAuthIdentity =
      isConnected && address
        ? {
            status: "connected",
            isConnected: true,
            address,
            walletKind: "smart-account",
            aaMode: userAAMode ?? "4337",
            SmartAccount4337: userSmartAccount4337 ?? address,
            Delegation7702: userDelegation7702 ?? undefined,
            sponsored: sponsorshipEnabled,
            sponsorProvider: sponsorshipEnabled ? "coinbase" : "self",
            sponsorAccount: undefined,
            chainId: chainId ?? undefined,
            walletProvider: "baseAccount",
            authMethod: undefined,
          }
        : {
            ...AOMI_AUTH_DISCONNECTED_IDENTITY,
            chainId: chainId ?? undefined,
            walletProvider: "baseAccount",
          };

    const connect = async () => {
      if (!connectAsync || !baseConnector) return;
      await connectAsync({ connector: baseConnector });
    };
    const disconnect = async () => {
      if (!disconnectAsync) return;
      await disconnectAsync();
    };

    return {
      identity,
      isReady: true,
      isSwitchingChain: isSwitchingChain || isConnecting || isDisconnecting,
      accounts: [],
      selectAccount: async () => undefined,
      canConnect:
        Boolean(connectAsync && baseConnector) && !identity.isConnected,
      canOpenAccountUI: false,
      canDisconnect: Boolean(disconnectAsync) && identity.isConnected,
      supportedChains: wagmiConfig.chains,
      supportedNetworks: {
        evm: wagmiConfig.chains,
        solana: supportedSolanaNetworks,
      },
      connect: async () => {
        await connect();
      },
      disconnect,
      switchChain: switchChainAsync
        ? async (nextChainId: number) => {
            setSelectedEvmChainId(nextChainId);
            await switchChainAsync({ chainId: nextChainId });
          }
        : undefined,
      selectNetwork: async (target) => {
        if (target.family !== "evm") return;
        setSelectedEvmChainId(target.chainId);
        if (switchChainAsync && chainId !== target.chainId && isConnected) {
          await switchChainAsync({ chainId: target.chainId });
        }
      },
      sendTransaction: sendTransactionAsync
        ? async (payload: WalletTxPayload) => {
            const result = await executeAdapterTransaction({
              payload,
              state: {
                currentChainId: chainId,
                capabilities,
                nativeWalletExecution: {
                  executionKind: "base_account_4337",
                  sendCallsTimeoutMs:
                    sponsorship?.mode === "optional" ||
                    sponsorship?.mode === "required"
                      ? sponsorship.sendCallsTimeoutMs
                      : undefined,
                  sponsorship:
                    sponsorship?.mode === "optional" ||
                    sponsorship?.mode === "required"
                      ? {
                          mode: sponsorship.mode,
                          getPaymasterServiceContext: (nextChainId) =>
                            typeof sponsorship.paymasterServiceContext ===
                            "function"
                              ? sponsorship.paymasterServiceContext(nextChainId)
                              : sponsorship.paymasterServiceContext,
                          getPaymasterServiceUrl: (nextChainId) =>
                            typeof sponsorship.paymasterServiceUrl ===
                            "function"
                              ? sponsorship.paymasterServiceUrl(nextChainId)
                              : sponsorship.paymasterServiceUrl,
                        }
                      : { mode: "disabled" },
                },
                sendCallsSyncAsync,
                sendTransactionAsync,
                switchChainAsync,
                chainsById,
                getPreferredRpcUrl,
              },
            });
            // session.ts writes aa_mode / smart_account_4337 / delegation_7702
            // to UserState on tx-complete; identity rereads them via useUser.
            return result;
          }
        : undefined,
      signTypedData: signTypedDataAsync
        ? async (payload: WalletEip712Payload) => {
            const signArgs = toViemSignTypedDataArgs(payload);
            if (!signArgs) {
              throw new Error("Missing typed_data payload");
            }
            const signature = await signTypedDataAsync(signArgs as never);
            return { signature };
          }
        : undefined,
      signMessage: signMessageAsync
        ? async (payload: WalletEip712Payload) => {
            const messageArgs = toViemSignMessageArgs(payload);
            if (!messageArgs) {
              throw new Error("Missing non_typed_data payload");
            }
            const signature = await signMessageAsync(messageArgs as never);
            return { signature };
          }
        : undefined,
    };
  }, [
    address,
    capabilities,
    chainId,
    chainsById,
    connectAsync,
    connectors,
    disconnectAsync,
    isConnected,
    isConnecting,
    isDisconnecting,
    isSwitchingChain,
    selectedEvmChainId,
    setSelectedEvmChainId,
    sendCallsSyncAsync,
    sendTransactionAsync,
    signMessageAsync,
    signTypedDataAsync,
    sponsorship,
    supportedSolanaNetworks,
    switchChainAsync,
    userAAMode,
    userSmartAccount4337,
    userDelegation7702,
    wagmiConfig.chains,
  ]);

  return (
    <AomiAuthAdapterProvider value={adapter}>
      {children}
    </AomiAuthAdapterProvider>
  );
}

export function AomiBaseAccountProvider({
  children,
  appName,
  appLogoUrl,
  chains,
  includeBaseSepolia = false,
  sponsorship,
}: AomiBaseAccountProviderProps) {
  const preferredChains = useMemo(
    () =>
      chains ??
      (includeBaseSepolia ? ([base, baseSepolia] as const) : ([base] as const)),
    [chains, includeBaseSepolia],
  );
  const routing = useFullTestnet(preferredChains);
  const [queryClient] = useState(() => new QueryClient());
  const config = useMemo(
    () =>
      createBaseAccountConfig({
        appName,
        appLogoUrl,
        chains: routing.routedChains,
      }),
    [appLogoUrl, appName, routing.routedChains],
  );

  // `BaseAccountAdapterInner` reads per-tx AA fields from `useUser()`, so
  // mount `ExtUserProvider` here. The provider owns its own UserState
  // store — descendants of `AomiBaseAccountProvider` get one store,
  // siblings get their own.
  return (
    <AomiWalletNetworkPreferencesProvider
      evmChains={routing.routedChains}
      solanaNetworks={[]}
    >
      <ExtUserProvider>
        <WagmiProvider config={config}>
          <QueryClientProvider client={queryClient}>
            <BaseAccountAdapterInner sponsorship={sponsorship}>
              {children}
            </BaseAccountAdapterInner>
          </QueryClientProvider>
        </WagmiProvider>
      </ExtUserProvider>
    </AomiWalletNetworkPreferencesProvider>
  );
}

"use client";

import { useMemo } from "react";
import type { Address, Chain } from "viem";
import { getWalletClient } from "wagmi/actions";
import {
  useAccount,
  useCapabilities,
  useConfig,
  useConnect,
  useConnections,
  useConnectors,
  useDisconnect,
  useReconnect,
  useSendCallsSync,
  useSendTransaction,
  useSignMessage,
  useSignTypedData,
  useSwitchAccount,
  useSwitchChain,
  useWalletClient,
} from "wagmi";
import type { Connector } from "wagmi";
import type { executeWalletCalls } from "@aomi-labs/react";
import { normalizeAtomicCapabilities } from "./wallet-execution";
import { walletDebug } from "./wallet-debug";

export type WagmiAccountShape = {
  address?: `0x${string}`;
  chainId?: number;
  isConnected: boolean;
  connector?: { id?: string; name?: string; type?: string; uid?: string };
};

export type WagmiConfigShape = {
  chains: readonly Chain[];
  connectors: readonly Connector[];
};

const DISCONNECTED_WAGMI_ACCOUNT: WagmiAccountShape = {
  address: undefined,
  chainId: undefined,
  isConnected: false,
};

const DISCONNECTED_WAGMI_CONFIG: WagmiConfigShape = {
  chains: [],
  connectors: [],
};

export function useSafeWagmiAccount(): WagmiAccountShape {
  try {
    return useAccount() as WagmiAccountShape;
  } catch {
    return DISCONNECTED_WAGMI_ACCOUNT;
  }
}

export function useSafeWalletClient(): {
  walletClient?: ReturnType<typeof useWalletClient>["data"];
} {
  try {
    const { data } = useWalletClient();
    return { walletClient: data };
  } catch {
    return { walletClient: undefined };
  }
}

export function useSafeGetWalletClientFor(): (args: {
  connector?: Connector;
  chainId?: number;
}) => Promise<ReturnType<typeof useWalletClient>["data"] | null> {
  try {
    const config = useConfig();
    return async ({ connector, chainId }) => {
      if (!connector) return null;
      try {
        return await getWalletClient(config, { connector, chainId } as never);
      } catch (error) {
        walletDebug("aa:wallet-client-failed", {
          connector: connector.id,
          chainId,
          error: error instanceof Error ? error.message : String(error),
        });
        return null;
      }
    };
  } catch {
    return async () => null;
  }
}

export function useSafeWagmiConfig(): WagmiConfigShape {
  try {
    const config = useConfig();
    return {
      chains: config.chains ?? [],
      connectors: config.connectors ?? [],
    };
  } catch {
    return DISCONNECTED_WAGMI_CONFIG;
  }
}

export function useSafeSwitchChain(): {
  switchChainAsync?: (args: {
    chainId: number;
    connector?: Connector;
  }) => Promise<unknown>;
  isPending: boolean;
} {
  try {
    const result = useSwitchChain();
    return {
      switchChainAsync: result.switchChainAsync,
      isPending: result.isPending,
    };
  } catch {
    return {
      switchChainAsync: undefined,
      isPending: false,
    };
  }
}

export function useSafeSendTransaction(): {
  sendTransactionAsync?: (args: {
    chainId?: number;
    connector?: Connector;
    to: `0x${string}`;
    value?: bigint;
    data?: `0x${string}`;
  }) => Promise<string>;
} {
  try {
    return useSendTransaction() as {
      sendTransactionAsync?: (args: {
        chainId?: number;
        connector?: Connector;
        to: `0x${string}`;
        value?: bigint;
        data?: `0x${string}`;
      }) => Promise<string>;
    };
  } catch {
    return { sendTransactionAsync: undefined };
  }
}

export function useSafeSignTypedData(): {
  signTypedDataAsync?: (args: unknown) => Promise<string>;
} {
  try {
    return useSignTypedData() as {
      signTypedDataAsync?: (args: unknown) => Promise<string>;
    };
  } catch {
    return { signTypedDataAsync: undefined };
  }
}

export function useSafeSignMessage(): {
  signMessageAsync?: (args: unknown) => Promise<string>;
} {
  try {
    return useSignMessage() as {
      signMessageAsync?: (args: unknown) => Promise<string>;
    };
  } catch {
    return { signMessageAsync: undefined };
  }
}

export function useSafeCapabilities(args?: {
  account?: Address;
  connector?: Connector;
}): {
  capabilities?: Parameters<typeof executeWalletCalls>[0]["capabilities"];
} {
  try {
    const { data } = useCapabilities(
      args?.account && args.connector
        ? ({
            account: args.account,
            connector: args.connector,
          } as never)
        : undefined,
    );
    return {
      capabilities: normalizeAtomicCapabilities(
        data as Parameters<typeof executeWalletCalls>[0]["capabilities"],
      ),
    };
  } catch {
    return { capabilities: undefined };
  }
}

export function useSafeSendCallsSync(): {
  sendCallsSyncAsync?: Parameters<
    typeof executeWalletCalls
  >[0]["sendCallsSyncAsync"];
} {
  try {
    const { sendCallsSyncAsync } = useSendCallsSync();
    return {
      sendCallsSyncAsync: async ({
        calls,
        capabilities,
        chainId,
        connector,
        forceAtomic,
        pollingInterval,
        status,
        throwOnFailure,
        timeout,
        version,
      }) => {
        return sendCallsSyncAsync({
          calls,
          capabilities,
          chainId,
          connector: connector as Connector | undefined,
          forceAtomic,
          pollingInterval,
          status,
          throwOnFailure,
          timeout,
          version,
        });
      },
    };
  } catch {
    return { sendCallsSyncAsync: undefined };
  }
}

export function useSafeConnect(): {
  connectAsync?: ReturnType<typeof useConnect>["connectAsync"];
  isPending: boolean;
} {
  try {
    const { connectAsync, isPending } = useConnect();
    return { connectAsync, isPending };
  } catch {
    return { connectAsync: undefined, isPending: false };
  }
}

export function useSafeDisconnect(): {
  disconnectAsync?: ReturnType<typeof useDisconnect>["disconnectAsync"];
  isPending: boolean;
} {
  try {
    const { disconnectAsync, isPending } = useDisconnect();
    return { disconnectAsync, isPending };
  } catch {
    return { disconnectAsync: undefined, isPending: false };
  }
}

export function useSafeReconnect(): {
  reconnect?: ReturnType<typeof useReconnect>["reconnect"];
  reconnectAsync?: ReturnType<typeof useReconnect>["reconnectAsync"];
} {
  try {
    const { reconnect, reconnectAsync } = useReconnect();
    return { reconnect, reconnectAsync };
  } catch {
    return { reconnect: undefined, reconnectAsync: undefined };
  }
}

export function useSafeConnectors(): ReturnType<typeof useConnectors> {
  try {
    return useConnectors();
  } catch {
    return [];
  }
}

export type WagmiConnectionShape = {
  connectorId: string;
  connectorName: string;
  address: `0x${string}`;
  chainId?: number;
};

export type RawWagmiConnectionShape = {
  connectorId: string;
  connectorUid: string;
  connectorName: string;
  accounts: readonly `0x${string}`[];
  chainId?: number;
};

export function useSafeRawWagmiConnections(): RawWagmiConnectionShape[] {
  try {
    const connections = useConnections();
    return useMemo(
      () =>
        connections.map((connection) => ({
          connectorId: connection.connector.id,
          connectorUid: connection.connector.uid,
          connectorName: connection.connector.name,
          accounts: connection.accounts.filter(
            (address): address is `0x${string}` => address.startsWith("0x"),
          ),
          chainId: connection.chainId,
        })),
      [connections],
    );
  } catch {
    return [];
  }
}

export function useSafeConnections(): WagmiConnectionShape[] {
  try {
    const connections = useConnections();
    // Memoized on the store snapshot so consumers (adapter memos, effects)
    // see a stable identity when nothing actually changed.
    return useMemo(
      () =>
        connections.flatMap((connection) =>
          connection.accounts
            .filter((address): address is `0x${string}` =>
              address.startsWith("0x"),
            )
            .map((address) => ({
              connectorId: connection.connector.uid,
              connectorName: connection.connector.name,
              address,
              chainId: connection.chainId,
            })),
        ),
      [connections],
    );
  } catch {
    return [];
  }
}

export function useSafeSwitchAccount(): {
  switchAccountAsync?: (args: {
    connector: Parameters<
      ReturnType<typeof useSwitchAccount>["switchAccountAsync"]
    >[0]["connector"];
  }) => Promise<unknown>;
} {
  try {
    const { switchAccountAsync } = useSwitchAccount();
    return { switchAccountAsync };
  } catch {
    return { switchAccountAsync: undefined };
  }
}

"use client";

import type { Chain } from "viem";
import type {
  NativeWalletExecutionPolicy as ClientNativeWalletExecutionPolicy,
  SponsorshipPaymasterServiceContext,
  WalletTxPayload,
} from "@aomi-labs/react";
import {
  DISABLED_PROVIDER_STATE,
  aaModeFromExecutionKind,
  executeWalletCalls,
  toAAWalletCalls,
} from "@aomi-labs/react";
import type { AomiTxResult } from "./types";

export type RequestedAAMode = "none" | "4337" | "7702";
export type WalletProviderState = Parameters<
  typeof executeWalletCalls
>[0]["providerState"];
export type WalletExecutionCallList = Parameters<
  typeof executeWalletCalls
>[0]["callList"];

export type WalletExecutionAdapterState = {
  currentChainId?: number;
  capabilities?: Parameters<typeof executeWalletCalls>[0]["capabilities"];
  nativeWalletExecution?: NativeWalletExecutionPolicy;
  sendCallsSyncAsync?: Parameters<
    typeof executeWalletCalls
  >[0]["sendCallsSyncAsync"];
  sendTransactionAsync?: Parameters<
    typeof executeWalletCalls
  >[0]["sendTransactionAsync"];
  switchChainAsync?: Parameters<
    typeof executeWalletCalls
  >[0]["switchChainAsync"];
  chainsById: Record<number, Chain>;
  getPreferredRpcUrl?: (chain: Chain) => string;
};

export type NativeWalletExecutionPolicy = Omit<
  ClientNativeWalletExecutionPolicy,
  "sponsorship"
> & {
  sponsorship?:
    | { mode: "disabled" }
    | {
        mode: "optional";
        getPaymasterServiceContext?: (
          chainId: number,
        ) => SponsorshipPaymasterServiceContext | undefined;
        getPaymasterServiceUrl?: (chainId: number) => string | undefined;
      }
    | {
        mode: "required";
        getPaymasterServiceContext?: (
          chainId: number,
        ) => SponsorshipPaymasterServiceContext | undefined;
        getPaymasterServiceUrl?: (chainId: number) => string | undefined;
      };
};

export type ResolveAAProviderState = (params: {
  callList: WalletExecutionCallList;
  chainsById: Record<number, Chain>;
  requestedMode: Exclude<RequestedAAMode, "none">;
  shouldUseExternalSigner: boolean;
  sponsored?: boolean;
}) => Promise<{
  providerState: WalletProviderState;
  resolvedMode: RequestedAAMode;
  fallbackReason?: string;
}>;

export function getPreferredRpcUrl(chain: Chain): string {
  return chain.rpcUrls.default.http[0] ?? chain.rpcUrls.public?.http[0] ?? "";
}

export function resolveRequestedAAMode(
  payload: WalletTxPayload,
  isBatch: boolean,
  preferAAForSingleCall = false,
  forceAA = false,
): RequestedAAMode {
  if (!forceAA && !isBatch && !preferAAForSingleCall) return "none";
  if (!forceAA && payload.aaPreference === "none" && isBatch) return "none";
  if (payload.aaPreference === "eip4337") return "4337";
  return "7702";
}

export function normalizeAtomicCapabilities(
  raw: Parameters<typeof executeWalletCalls>[0]["capabilities"] | undefined,
): Parameters<typeof executeWalletCalls>[0]["capabilities"] | undefined {
  if (!raw) return undefined;

  const normalized: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {
    if (!value || typeof value !== "object" || Array.isArray(value)) {
      normalized[key] = value;
      continue;
    }

    const record = value as {
      atomic?: { status?: string };
      [field: string]: unknown;
    };
    normalized[key] =
      record.atomic?.status === "ready"
        ? {
            ...record,
            atomic: {
              ...record.atomic,
              status: "supported",
            },
          }
        : value;
  }

  return normalized as Parameters<typeof executeWalletCalls>[0]["capabilities"];
}

function buildAaAttempts(
  aaRequestedMode: RequestedAAMode,
  shouldUseExternalSigner: boolean,
): Array<{
  requestedMode: Exclude<RequestedAAMode, "none">;
  sponsored?: boolean;
}> {
  if (aaRequestedMode === "7702") {
    if (shouldUseExternalSigner) {
      return [{ requestedMode: "4337", sponsored: true }];
    }
    return [
      { requestedMode: "7702" },
      { requestedMode: "4337", sponsored: true },
    ];
  }

  if (aaRequestedMode === "4337") {
    return [{ requestedMode: "4337", sponsored: true }];
  }

  return [];
}

function resolveNativeWalletExecutionPolicy({
  policy,
  chainId,
  requiresAtomicForBatch,
}: {
  policy?: NativeWalletExecutionPolicy;
  chainId: number;
  requiresAtomicForBatch: boolean;
}): ClientNativeWalletExecutionPolicy | undefined {
  if (!policy && !requiresAtomicForBatch) {
    return undefined;
  }

  const sponsorship =
    policy?.sponsorship?.mode === "optional" ||
    policy?.sponsorship?.mode === "required"
      ? {
          mode: policy.sponsorship.mode,
          paymasterServiceContext:
            policy.sponsorship.getPaymasterServiceContext?.(chainId),
          paymasterServiceUrl:
            policy.sponsorship.getPaymasterServiceUrl?.(chainId),
        }
      : policy?.sponsorship;

  return {
    executionKind: policy?.executionKind,
    requiresAtomicForBatch:
      requiresAtomicForBatch || policy?.requiresAtomicForBatch,
    sendCallsTimeoutMs: policy?.sendCallsTimeoutMs,
    sendCallsVersion: policy?.sendCallsVersion,
    sponsorship,
  };
}

function hasResolvedAAProviderState(
  providerState: WalletProviderState,
): boolean {
  return Boolean(providerState.resolved);
}

export async function executeAdapterTransaction({
  payload,
  state,
  shouldUseExternalSigner = false,
  resolveAAProviderState,
  preferAAForSingleCall = false,
  forceAA = false,
}: {
  payload: WalletTxPayload;
  state: WalletExecutionAdapterState;
  shouldUseExternalSigner?: boolean;
  resolveAAProviderState?: ResolveAAProviderState;
  preferAAForSingleCall?: boolean;
  forceAA?: boolean;
}): Promise<AomiTxResult> {
  if (!payload.to && (!payload.calls || payload.calls.length === 0)) {
    throw new Error("pending_transaction_missing_call_data");
  }

  if (!state.sendTransactionAsync) {
    throw new Error("wallet_send_transaction_not_supported");
  }
  const sendTransactionAsync = state.sendTransactionAsync;

  const callList = toAAWalletCalls(
    payload,
    payload.chainId ?? state.currentChainId ?? 1,
  );
  const isBatch = callList.length > 1;
  const aaRequestedMode = resolveRequestedAAMode(
    payload,
    isBatch,
    preferAAForSingleCall,
    forceAA,
  );
  const requiresSponsoredExecution =
    state.nativeWalletExecution?.sponsorship?.mode === "required";
  // Atomic-required is a payload-level intent (`aaStrict === true`),
  // independent of the provider's sponsorship mode. Conflating them
  // (commit 1d406d2) forces every sponsored batch into atomic+no-fallback
  // and breaks fee-injected 2-call batches when the wallet/bundler errors
  // after sign. `requiresSponsoredExecution` still drives fail-closed
  // semantics in the AA-failure exit path below.
  const requiresAtomicForBatch = isBatch && payload.aaStrict === true;
  const nativeWalletExecution = resolveNativeWalletExecutionPolicy({
    policy: state.nativeWalletExecution,
    chainId: callList[0]?.chainId ?? state.currentChainId ?? 1,
    requiresAtomicForBatch,
  });

  const executeWithProviderState = async (providerState: WalletProviderState) =>
    executeWalletCalls({
      callList,
      currentChainId: state.currentChainId ?? callList[0]?.chainId ?? 1,
      capabilities: state.capabilities,
      localPrivateKey: null,
      nativeWalletExecution,
      providerState,
      sendCallsSyncAsync: state.sendCallsSyncAsync
        ? async (args) => {
            return state.sendCallsSyncAsync?.({
              ...args,
            });
          }
        : async () => {
            throw new Error("wallet_send_calls_not_supported");
          },
      sendTransactionAsync,
      switchChainAsync: state.switchChainAsync
        ? async ({ chainId }) => {
            return state.switchChainAsync?.({ chainId });
          }
        : async () => {
            throw new Error("wallet_switch_chain_not_supported");
          },
      chainsById: state.chainsById,
      getPreferredRpcUrl: state.getPreferredRpcUrl ?? getPreferredRpcUrl,
    });

  let execution: Awaited<ReturnType<typeof executeWalletCalls>> | null = null;
  let finalFallbackReason: string | undefined;
  let lastAAError: unknown;
  let sawUnresolvedAAProviderState = false;
  const aaStateResolver = resolveAAProviderState;
  const aaAttempts = aaStateResolver
    ? buildAaAttempts(aaRequestedMode, shouldUseExternalSigner)
    : [];

  if (aaAttempts.length === 0) {
    execution = await executeWithProviderState(DISABLED_PROVIDER_STATE);
  } else {
    if (!aaStateResolver) {
      throw new Error("aa_provider_state_resolver_missing");
    }
    for (const attempt of aaAttempts) {
      const attemptState = await aaStateResolver({
        callList,
        chainsById: state.chainsById,
        requestedMode: attempt.requestedMode,
        shouldUseExternalSigner,
        sponsored: attempt.sponsored,
      });

      if (attemptState.fallbackReason && !finalFallbackReason) {
        finalFallbackReason = attemptState.fallbackReason;
      }

      if (!hasResolvedAAProviderState(attemptState.providerState)) {
        sawUnresolvedAAProviderState = true;
        continue;
      }

      try {
        execution = await executeWithProviderState(attemptState.providerState);
        if (
          aaRequestedMode === "7702" &&
          attempt.requestedMode === "4337" &&
          !finalFallbackReason
        ) {
          finalFallbackReason = "requested_7702_fallback_4337";
        }
        break;
      } catch (error) {
        lastAAError = error;
        console.warn("[aomi-auth-adapter] AA attempt failed", {
          requestedMode: attempt.requestedMode,
          error: error instanceof Error ? error.message : String(error),
        });
      }
    }

    if (!execution) {
      if (requiresSponsoredExecution) {
        throw new Error(finalFallbackReason ?? "aa_required_execution_failed");
      }
      if (payload.aaStrict && lastAAError && !sawUnresolvedAAProviderState) {
        throw new Error(finalFallbackReason ?? "aa_required_execution_failed");
      }
      console.warn(
        "[aomi-auth-adapter] All AA attempts failed; falling back to native wallet",
        {
          error:
            lastAAError instanceof Error
              ? lastAAError.message
              : String(lastAAError ?? "unknown"),
        },
      );
      execution = await executeWithProviderState(DISABLED_PROVIDER_STATE);
      finalFallbackReason = finalFallbackReason ?? "aa_failed_fallback_eoa";
    }
  }

  if (!execution.txHash) {
    throw new Error("wallet_execution_missing_transaction_hash");
  }

  const aaResolvedMode: RequestedAAMode =
    aaModeFromExecutionKind(execution.executionKind) ?? "none";

  return {
    txHash: execution.txHash,
    amount: payload.value,
    aaRequestedMode,
    aaResolvedMode,
    aaFallbackReason:
      finalFallbackReason ??
      (aaRequestedMode === "7702" && aaResolvedMode === "4337"
        ? "requested_7702_fallback_4337"
        : aaRequestedMode !== "none" && aaResolvedMode === "none"
          ? "aa_unavailable_fallback_eoa"
          : undefined),
    executionKind: execution.executionKind,
    batched: execution.batched,
    callCount: callList.length,
    sponsored: execution.sponsored,
    SmartAccount4337: execution.SmartAccount4337,
    Delegation7702: execution.Delegation7702,
  };
}
